SELECT ast.id, ast.approve_status AS approveStatus, ast.approve_user_id AS approveUserId, ast.approve_user_name AS approveUserName, ast.approve_time AS approveTime, ast.invalid_status AS invalidStatus, ast.invalid_remark AS invalidRemark, ast.invalid_time AS invalidTime, ast.code, ast.source_code AS sourceCode, ast.source_type AS sourceType, ast.source_id AS sourceId, asp.plan_name AS stocktakingPlanName, ast.asset_org_id AS assetOrgId, ast.asset_org_name AS assetOrgName, ast.remark, ast.create_time AS createTime, ast.create_user_name AS createUserName FROM asset_stocktaking ast LEFT JOIN asset_stocktaking_plan asp ON ast.source_id = asp.id AND asp.is_deleted = false WHERE ${params.sqlMap.default} AND ast.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
ast.create_time DESC

SELECT approve_status AS tabFlag, count(*) AS count FROM asset_stocktaking WHERE is_deleted=FALSE
${params.permissionSql}
GROUP BY approve_status
